// Generates the generated stylesheets of @gjuoun/bigface-ui from the two palettes and the role maps:
//
//   src/styles/tokens.css     the Bigface palette as --bf-* (the dark default)
//   src/themes/_reset.css     optional --theme-* keys → initial, per [data-theme] scope
//   src/themes/<id>.css       one file per theme: a light block and a dark block
//
//   bun run --cwd packages/ui theme:sync    rewrite every generated file in place
//   bun run --cwd packages/ui theme:check   fail when any of them is stale (CI uses this)
//
// The palettes stay the single source of colour: a theme names palette colours (src/themes/roles.ts),
// never hexes, so both modes come out of one role map and a palette edit flows through both.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import {
	OPTIONAL,
	REQUIRED,
	THEMES,
	type Theme,
	type Value,
} from "../src/themes/roles.ts";

export interface PaletteLike {
	colors: Record<string, { hex: string }>;
	ansi: Record<string, { hex: string }>;
}

const kebab = (name: string): string =>
	name
		.replace(/([a-z0-9])([A-Z])/g, "$1-$2")
		.replace(/_/g, "-")
		.toLowerCase();

/** The exact text of tokens.css for a palette. Deterministic: input order only, no timestamps. */
export function renderTokens(palette: PaletteLike): string {
	const colors = Object.entries(palette.colors).map(
		([name, c]) => "  --bf-" + kebab(name) + ": " + c.hex.toLowerCase() + ";",
	);
	const ansi = Object.entries(palette.ansi).map(
		([name, c]) =>
			"  --bf-ansi-" + kebab(name) + ": " + c.hex.toLowerCase() + ";",
	);
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from palette/bigface.json. Do not edit.",
		"   Bigface's dark theme: import it after theme.css, or skip it and set your own --bf-* values. */",
		":root {",
		...colors,
		...ansi,
		"  --ink-on-bright: var(--bf-bg);",
		"}",
		"",
	].join("\n");
}

const here = import.meta.dir;
export const tokensPath = join(here, "../src/styles/tokens.css");
export const themesDir = join(here, "../src/themes");
const palettePath = join(here, "../../bigface-tokens/palette/bigface.json");
const lightPalettePath = join(
	here,
	"../../bigface-tokens/palette/bigface-light.json",
);

const hexOf = (palette: PaletteLike, name: string): string => {
	const c = palette.colors[name] ?? palette.ansi[name];
	if (!c) throw new Error("no palette colour named " + name);
	return c.hex.toLowerCase();
};

/** One role value as CSS: a palette hex, a color-mix of two palette hexes, or a literal. */
export function cssValue(v: Value, palette: PaletteLike): string {
	if (typeof v === "string") return v;
	if ("color" in v) return hexOf(palette, v.color);
	const [a, pct, b] = v.mix;
	return (
		"color-mix(in oklab, " +
		hexOf(palette, a) +
		" " +
		pct +
		"%, " +
		hexOf(palette, b) +
		")"
	);
}

/** A theme's block for one mode, in contract order: every required key, then every optional key. */
export function renderBlock(theme: Theme, palette: PaletteLike): string {
	const keys = [...REQUIRED, ...OPTIONAL] as string[];
	const missing = keys.filter((k) => !(k in theme.roles));
	const extra = Object.keys(theme.roles).filter((k) => !keys.includes(k));
	if (missing.length)
		throw new Error(theme.id + ": missing roles " + missing.join(", "));
	if (extra.length)
		throw new Error(theme.id + ": unknown roles " + extra.join(", "));
	return keys
		.map(
			(k) =>
				"  --theme-" +
				k +
				": " +
				cssValue(theme.roles[k] as Value, palette) +
				";",
		)
		.join("\n");
}

/** Light selectors, dark selectors (the wiki's three-part rule), then the two blocks. */
export function renderThemeFile(
	theme: Theme,
	dark: PaletteLike,
	light: PaletteLike,
): string {
	const own = '[data-theme="' + theme.id + '"]';
	const lightSel = theme.isDefault ? ":root:not([data-theme]),\n" + own : own;
	const darkSel = [
		...(theme.isDefault ? [':root:not([data-theme])[data-mode="dark"]'] : []),
		own + '[data-mode="dark"]',
		'[data-mode="dark"] ' + own + ':not([data-mode="light"])',
	].join(",\n");
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from src/themes/roles.ts and the two palettes.",
		"   Do not edit: change the role map, then run theme:sync again. */",
		"",
		lightSel + " {",
		renderBlock(theme, light),
		"}",
		"",
		darkSel + " {",
		renderBlock(theme, dark),
		"}",
		"",
	].join("\n");
}

/** _reset.css: optional keys go back to the contract default inside every theme scope. */
export function renderReset(): string {
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from contract.json. Do not edit.",
		"   Custom properties inherit, so a nested theme scope would otherwise keep the outer theme's",
		"   optional values. initial is the guaranteed-invalid value: the mapping's var() fallback wins. */",
		"",
		"[data-theme] {",
		...OPTIONAL.map((k) => "  --theme-" + k + ": initial;"),
		"}",
		"",
	].join("\n");
}

/** Every file theme:sync writes, as path → contents. */
export function renderAll(
	dark: PaletteLike,
	light: PaletteLike,
): Record<string, string> {
	const files: Record<string, string> = {
		[tokensPath]: renderTokens(dark),
		[join(themesDir, "_reset.css")]: renderReset(),
	};
	for (const theme of THEMES) {
		files[join(themesDir, theme.id + ".css")] = renderThemeFile(
			theme,
			dark,
			light,
		);
	}
	return files;
}

const read = (p: string) => JSON.parse(readFileSync(p, "utf8")) as PaletteLike;

if (import.meta.main) {
	const files = renderAll(read(palettePath), read(lightPalettePath));
	const check = process.argv.includes("--check");
	let stale = 0;
	for (const [path, next] of Object.entries(files)) {
		const current = existsSync(path) ? readFileSync(path, "utf8") : "";
		if (!check) {
			writeFileSync(path, next);
			console.log("wrote " + path);
			continue;
		}
		if (current !== next) {
			console.error("stale: " + path);
			stale++;
		}
	}
	if (check) {
		if (stale) {
			console.error(stale + " file(s) stale: run theme:sync");
			process.exit(1);
		}
		console.log(
			"theme files are up to date (" + Object.keys(files).length + ")",
		);
	}
}
